typedef float time_value_t;

struct PhotoChallenge
{
    char pad[0x28];
    int numTaken;
    int GetNumTaken() { return numTaken; }
};

struct BeachChallenges
{
    PhotoChallenge *photo;
};

struct Beach
{
    char pad[0x2D8];
    BeachChallenges challenges;
    BeachChallenges *get_challenges() { return &challenges; }
};

struct Game
{
    char pad[0x74];
    int game_mode;
    int get_game_mode() { return game_mode; }
};

struct PauseMenuSystem
{
    enum Menu
    {
        PhotoMenu = 17
    };

    char pad0[0x7C];
    int active;
    char pad1[0x0C];
    void *menu_vtable;
    int draw;

    void startDraw(int menu);
    void UpdateButtonDown();
};

struct FEManager
{
    char pad[4];
    PauseMenuSystem *pms;
};

struct PHOTOS
{
    int waitingOnMenu;
};

class IGOFrontEnd
{
public:
    enum RUNSTATE
    {
        RUNSTATE_NORMAL,
        RUNSTATE_GOALS,
        RUNSTATE_REWARDS,
        RUNSTATE_STATS,
        RUNSTATE_HIGHSCORE,
        RUNSTATE_PHOTOS,
        RUNSTATE_SAVE
    };

    char pad0[0xBC];
    FEManager *manager;
    char pad1[0x68];
    RUNSTATE runState;
    char pad2[0xD0];
    PHOTOS photos;

    void ShowAccompBackground(bool enabled, int h = 0, int v = 0);
    void UpdateStateSave(time_value_t time_inc);
    void UpdateStatePhotos(time_value_t time_inc);
};

extern Game *g_game_ptr;
extern Beach *g_beach_ptr;

__asm__(".equ g_game_ptr, 0x0045AC64");
__asm__(".equ g_beach_ptr, 0x0042F710");
__asm__(".equ startDraw__15PauseMenuSystemi, 0x00100000");
__asm__(".equ UpdateButtonDown__15PauseMenuSystem, 0x00100000");
__asm__(".equ ShowAccompBackground__11IGOFrontEndbii, 0x0017CC88");
__asm__(".equ UpdateStateSave__11IGOFrontEndf, 0x00177C00");

enum
{
    GAME_MODE_CAREER = 0
};

void IGOFrontEnd::UpdateStatePhotos(time_value_t time_inc)
{
	bool	advanceState = false;
	bool	popup = true;

	if (photos.waitingOnMenu == -1)
	{
		// Only popup menu in career mode beaches with photo challenges.
		if (g_game_ptr->get_game_mode() != GAME_MODE_CAREER || !g_beach_ptr->get_challenges()->photo)
			popup = false;
		// Only popup menu if some photos were taken this run.
		else if (g_beach_ptr->get_challenges()->photo->GetNumTaken() == 0)
			popup = false;
		// If there is nothing to overwrite and we only took one photo, then don't popup menu.
/*		else if (g_beach_ptr->get_challenges()->photo->GetNumTaken() == 1 && !g_career->PhotoExistsForLevel (g_game_ptr->get_level_id()))
			popup = false;*/
	}

	if (popup)
	{
		// First frame: popup photo menu.
		if ((manager->pms->active != PauseMenuSystem::PhotoMenu || !manager->pms->draw) &&
			photos.waitingOnMenu == -1)
		{
			manager->pms->startDraw(PauseMenuSystem::PhotoMenu);
			manager->pms->UpdateButtonDown();
			photos.waitingOnMenu = manager->pms->active;
			ShowAccompBackground(true);
		}
		// Wait for photo menu to finish.
		else if (photos.waitingOnMenu != -1 && !manager->pms->draw)
		{
			advanceState = true;
		}
	}
	else
	{
		advanceState = true;
	}

	// Photo menu finished, proceed with normal end run states.
	if (advanceState)
	{
		ShowAccompBackground(false);
		photos.waitingOnMenu = -1;
		runState = RUNSTATE_SAVE;
		UpdateStateSave(time_inc);
	}
}
